"""Shared bound command execution for CLI and local app requests."""
from __future__ import annotations

import importlib
import json
from pathlib import Path
import shlex
import subprocess
import os
import re

from cli import v1
from cli.product_boundary import engine_boundary
from cli.v1_io import Refusal

HANDLERS = {
    'review': ('review', 'run_review'),
    'check-ok': ('check_ok', 'run_check_ok'),
    'check-if-ok': ('check_ok', 'run_check_ok'),
    'verify-step': ('verify_step', 'run_verify_step_command'),
    'honesty-status': ('honesty_status', 'run_honesty_status_command'),
    'ledger': ('ledger', 'run_ledger_command'),
    'route': ('route', 'run_route_command'),
    'handover-compact': ('handover_compact', 'run_handover_compact_command'),
    'app': ('app', 'run_app'),
    'hosted-dashboard': ('hosted_dashboard', 'run_hosted_dashboard'),
    'land-check': ('land_check', 'run_land_check_command'),
    'land-closeout': ('land_closeout', 'run_land_closeout_command'),
    'pr-land': ('pr_land', 'run_pr_land_command'),
}


class CapturedOutput:
    json_mode = True
    quiet = False
    verbose = False
    no_color = True

    def __init__(self):
        self.payload = None
        self.messages = []

    def emit_json(self, value):
        self.payload = value

    def emit(self, value):
        self.messages.append(str(value))

    error = warn = debug = emit


class BoundRunner:
    """Argv-only transport, fixed repository, no ambient shell or Muse binary."""
    def __init__(self, boundary):
        self.boundary = boundary

    def run(self, command, *, cwd=None):
        from adapters.runner import CommandResult
        b = self.boundary
        if cwd is not None and Path(cwd).resolve() != b.context.root:
            raise Refusal('engine_runner_repository_mismatch')
        argv = shlex.split(command)
        if not argv:
            raise Refusal('empty_command')
        b.recheck()
        if argv[0] == 'git':
            allowed = {'rev-parse', 'status', 'log', 'show', 'diff', 'merge-base',
                       'symbolic-ref', 'ls-files', 'for-each-ref', 'remote'}
            if len(argv) < 2 or argv[1] not in allowed:
                raise Refusal('engine_git_mutation_requires_explicit_service')
            if argv[1] == 'remote' and argv[2:3] != ['get-url']:
                raise Refusal('engine_remote_read_only')
            value = v1.git(b.context.root, *argv[1:], optional=True)
            return CommandResult(value, '', 0 if value else 1)
        if argv[0] == 'gh' and getattr(b.args, 'allow_network', False):
            result = gh_run(b, argv)
            return CommandResult(result.stdout.strip(), result.stderr.strip(), result.returncode)
        raise Refusal('engine_transport_not_authorized')


def gh_run(boundary, argv):
    executable = getattr(boundary.args, 'gh', None)
    if not getattr(boundary.args, 'allow_network', False) or not executable:
        raise Refusal('remote_requires_allow_network_and_explicit_gh')
    path = Path(executable)
    if not path.is_absolute() or path.resolve() != path or not path.is_file():
        raise Refusal('gh_executable_must_be_physical')
    boundary.recheck()
    remote = boundary.context.config['vcs']['git']['remote']
    url = v1.git(boundary.context.root, 'remote', 'get-url', remote, optional=True)
    match = re.fullmatch(r'(?:https://github\.com/|git@github\.com:)([A-Za-z0-9_.-]+/[A-Za-z0-9_.-]+?)(?:\.git)?', url)
    if not match:
        raise Refusal('gh_requires_bound_github_remote')
    env = {k: v for k, v in os.environ.items() if not k.startswith('GIT_') and k not in ('GH_REPO', 'GH_HOST')}
    env.update(GH_REPO='github.com/' + match[1], GH_HOST='github.com', GH_PROMPT_DISABLED='1')
    return subprocess.run([str(path), *argv[1:]], cwd=boundary.context.root,
                          env=env, capture_output=True, text=True, timeout=60)


def mutates(args):
    if args.command in {'review', 'check-ok', 'check-if-ok'}:
        return not args.dry_run and (args.command != 'review' or not args.no_stamp)
    return (getattr(args, 'write', False) or getattr(args, 'post_land_sync', False) or args.command == 'land-check' or
            (args.command == 'verify-step' and not args.dry_run) or
            (args.command == 'ledger' and args.ledger_action == 'append'))


def invoke(context, args, *, provider_factory=None, script_executor=None):
    from cli.context import CliContext
    output = CapturedOutput()
    args.repo = str(context.root)
    # Reviewer --model is a policy label, not a context identity selector.
    with engine_boundary(context, args, writable=mutates(args)) as boundary:
        lane = getattr(args, 'lane', None)
        if lane is not None and lane not in context.config['docs']['lanes']:
            raise Refusal('unknown_lane')
        from cli.product_migration import inventory
        for row in inventory(context.root, context.config):
            boundary.watch(row['path'])
        if args.command in {'review', 'check-ok', 'check-if-ok'}:
            provider = args.provider or boundary.model.adapter.freeze_contract.reviewer.provider
            if provider == 'api' and not args.dry_run and not getattr(args, 'allow_network', False) and provider_factory is None:
                raise Refusal('api_review_requires_explicit_allow_network')
        ctx = CliContext(kit=v1.KIT, cwd=context.root, runner=BoundRunner(boundary), output=output,
                         review_provider_factory=provider_factory, script_executor=script_executor)
        ctx.bound_context = context
        ctx.bound_args = args
        if args.command == 'governance-sync':
            from cli.product_governance import run
            payload = run(boundary)
            code = payload.get('exit_code', 0 if payload['ok'] else 2)
        elif args.command in {'land-check', 'land-closeout'}:
            from cli.product_landing import run
            payload = run(boundary)
            code = payload['exit_code']
        elif args.command == 'workspace':
            from cli.product_workspace import report
            payload = report(context, args)
            code = payload['exit_code']
        else:
            module, name = HANDLERS[args.command]
            code = getattr(importlib.import_module('cli.commands.' + module), name)(args, ctx)
            payload = output.payload
        boundary.recheck()
    if payload is None:
        payload = {'ok': code == 0, 'exit_code': code, 'messages': output.messages}
    else:
        payload = dict(payload, ok=code == 0, exit_code=code)
        if output.messages:
            payload['messages'] = output.messages
    return code, payload


def execute(context, args):
    code, payload = invoke(context, args)
    if args.json or not args.quiet:
        print(json.dumps(payload, indent=None if args.json else 2))
    return code

"""GET/HEAD-only upstream HTTP client with host allowlist (§HGD.6.6, §HGD.11)."""

from __future__ import annotations

import json
import urllib.error
import urllib.request
from dataclasses import dataclass
from typing import Any, Callable
from urllib.parse import urlparse

from tools.hosted_dashboard.hosts import url_host_allowed

ALLOWED_METHODS = frozenset({"GET", "HEAD"})


class UpstreamError(Exception):
    """Upstream fetch failure with frozen error token."""

    def __init__(self, token: str, *, status: int | None = None, detail: str | None = None) -> None:
        super().__init__(token)
        self.token = token
        self.status = status
        self.detail = detail


@dataclass(frozen=True)
class UpstreamResponse:
    """Raw upstream response."""

    status: int
    headers: dict[str, str]
    body: bytes


Transport = Callable[[str, str, dict[str, str], float], UpstreamResponse]


def _default_transport(method: str, url: str, headers: dict[str, str], timeout: float) -> UpstreamResponse:
    if method not in ALLOWED_METHODS:
        raise UpstreamError("method_refused", detail=f"method {method} not allowed")
    request = urllib.request.Request(url, method=method, headers=headers)
    try:
        with urllib.request.urlopen(request, timeout=timeout) as response:
            body = response.read() if method == "GET" else b""
            return UpstreamResponse(
                status=int(response.status),
                headers={k.lower(): v for k, v in response.headers.items()},
                body=body,
            )
    except urllib.error.HTTPError as exc:
        body = exc.read() if method == "GET" else b""
        return UpstreamResponse(
            status=int(exc.code),
            headers={k.lower(): v for k, v in exc.headers.items()} if exc.headers else {},
            body=body,
        )
    except urllib.error.URLError as exc:
        raise UpstreamError("upstream_unreachable", detail=str(exc.reason)) from exc


class UpstreamClient:
    """Host-allowlisted GET/HEAD client for GitHub/MuseHub read APIs."""

    def __init__(
        self,
        *,
        token: str | None,
        extra_allowed_hosts: frozenset[str] | None = None,
        transport: Transport | None = None,
        timeout: float = 15.0,
        user_agent: str = "overseer-hosted-dashboard/0.1",
    ) -> None:
        self._token = token
        self._extra = extra_allowed_hosts or frozenset()
        self._transport = transport or _default_transport
        self._timeout = timeout
        self._user_agent = user_agent

    def request(self, method: str, url: str, *, accept: str = "application/json") -> UpstreamResponse:
        method_upper = method.upper()
        if method_upper not in ALLOWED_METHODS:
            raise UpstreamError("method_refused", detail=f"method {method} not allowed")
        if not url_host_allowed(url, extra_allowed=self._extra):
            raise UpstreamError("upstream_host_refused")
        headers = {
            "Accept": accept,
            "User-Agent": self._user_agent,
        }
        if self._token:
            headers["Authorization"] = f"Bearer {self._token}"
        return self._transport(method_upper, url, headers, self._timeout)

    def get_json(self, url: str) -> Any:
        """GET JSON; map upstream status codes to frozen error tokens."""
        response = self.request("GET", url, accept="application/vnd.github+json")
        return self._map_response(response, expect_json=True)

    def get_bytes(self, url: str, *, accept: str = "application/vnd.github.raw") -> bytes:
        """GET raw bytes for Contents/raw endpoints."""
        response = self.request("GET", url, accept=accept)
        return self._map_response(response, expect_json=False)  # type: ignore[return-value]

    def _map_response(self, response: UpstreamResponse, *, expect_json: bool) -> Any:
        if response.status == 404:
            raise UpstreamError("not_found", status=404)
        if response.status in {401, 403}:
            # Distinguishing rate limit vs auth: GitHub sends X-RateLimit-Remaining: 0
            remaining = response.headers.get("x-ratelimit-remaining")
            if remaining == "0" or response.status == 403 and "rate limit" in response.body.decode(
                "utf-8", errors="replace"
            ).lower():
                raise UpstreamError("upstream_rate_limited", status=response.status)
            raise UpstreamError("upstream_unauthorized", status=response.status)
        if response.status == 429:
            raise UpstreamError("upstream_rate_limited", status=429)
        if response.status < 200 or response.status >= 300:
            raise UpstreamError("upstream_error", status=response.status)
        if expect_json:
            try:
                return json.loads(response.body.decode("utf-8"))
            except (UnicodeDecodeError, json.JSONDecodeError) as exc:
                raise UpstreamError("upstream_error", detail="invalid json") from exc
        return response.body

"""Reviewed schema migration and confined, config-last foundation asset updates.

This is deliberately a collection of per-file atomic replacements, not a
transaction. A reviewed plan and byte-exact backups make interrupted progress
inspectable and retryable without guessing which version a file contains.
"""
from __future__ import annotations

import base64
import copy
import difflib
import fnmatch
import fcntl
import json
import os
from pathlib import Path
import re
import stat
import uuid
from argparse import Namespace

from cli.v1_io import Refusal, atomic as _atomic, confined, digest, read as _read, LIMIT

ASSET_LIMIT = 16 * 1024 * 1024


def read(root, relative, **kwargs):
    return _read(root, relative, limit=LIMIT if relative in (CONFIG, NEXT) else ASSET_LIMIT, **kwargs)


def atomic(root, relative, data, **kwargs):
    return _atomic(root, relative, data, limit=LIMIT if relative in (CONFIG, NEXT) else ASSET_LIMIT, **kwargs)

CONFIG = ".overseer/config.yaml"
NEXT = "docs/NEXT.md"
LOCK = ".overseer/version.lock"
LAUNCHER = ".overseer/bin/ok"
HOOKS = (".cursor/hooks.json", ".cursor/hooks/session-start-next.sh",
         ".cursor/hooks/session-end-closeout.sh", ".overseer/instructions/bookends.md")


def _json(value):
    return (json.dumps(value, sort_keys=True, indent=2, ensure_ascii=False) + "\n").encode()


def _plan_shape(plan):
    required = {"plan_version", "operation", "source_schema", "repository", "source_config_sha256",
                "normalized_config", "field_map", "diagnostics", "refresh_runtime", "context", "assets",
                "protected", "classification", "legacy_prompt_drafts", "next", "apply_supported"}
    if not isinstance(plan, dict) or set(plan) != required:
        raise Refusal("migration_plan_invalid")
    for field in ("normalized_config", "repository", "context"):
        if not isinstance(plan[field], dict):
            raise Refusal("migration_plan_invalid")
    for field in ("assets", "protected", "field_map", "diagnostics", "classification", "legacy_prompt_drafts"):
        if not isinstance(plan[field], (list, tuple)):
            raise Refusal("migration_plan_invalid")
    if (type(plan["refresh_runtime"]) is not bool or type(plan["apply_supported"]) is not bool or
            not isinstance(plan["source_config_sha256"], str) or
            not re.fullmatch(r"[0-9a-f]{64}", plan["source_config_sha256"])):
        raise Refusal("migration_plan_invalid")

    def snapshot(row):
        if (not isinstance(row, dict) or set(row) != {"path", "sha256", "mode"} or
                not isinstance(row["path"], str) or not isinstance(row["sha256"], str) or
                not re.fullmatch(r"absent|[0-9a-f]{64}", row["sha256"]) or
                ((row["sha256"] == "absent") != (row["mode"] is None)) or
                (row["mode"] is not None and (type(row["mode"]) is not int or not 0 <= row["mode"] <= 0o7777))):
            raise Refusal("migration_plan_snapshot_invalid")

    for row in plan["protected"]:
        snapshot(row)
    for row in plan["assets"]:
        if (not isinstance(row, dict) or set(row) != {"path", "before", "after", "mode", "content_b64"} or
                not isinstance(row["path"], str) or not isinstance(row["after"], str) or
                not re.fullmatch(r"[0-9a-f]{64}", row["after"]) or type(row["mode"]) is not int or
                not 0 <= row["mode"] <= 0o7777 or not isinstance(row["content_b64"], str)):
            raise Refusal("migration_plan_asset_invalid")
        snapshot(row["before"])


def _snapshot(root, path):
    target = confined(root, path, missing_parents=True)
    body = read(root, path, missing=True)
    return {"path": path, "sha256": "absent" if body is None else digest(body),
            "mode": None if body is None else stat.S_IMODE(target.stat().st_mode)}


def _same(root, row):
    return _snapshot(root, row["path"]) == row


def _lock_entries(root):
    from cli.v1 import decode
    raw = read(root, LOCK, missing=True)
    if raw is None:
        return {}
    value = decode(raw)
    if not isinstance(value, dict) or not isinstance(value.get("footprint"), list):
        raise Refusal("footprint_lock_invalid")
    entries = {}
    for entry in value["footprint"]:
        if (not isinstance(entry, dict) or not isinstance(entry.get("path"), str)
                or entry["path"] in entries or entry.get("origin", "kit") not in ("kit", "preserved")
                or not isinstance(entry.get("sha256"), str)):
            raise Refusal("footprint_lock_entry_invalid")
        confined(root, entry["path"], missing_parents=True)
        entries[entry["path"]] = entry
    return entries


def _bound_launcher(body, root, config):
    """B's launcher template is retained exactly; custom additions are user-owned."""
    from cli import v1
    return body is not None and body == v1.launcher(root, config["repo"]["id"])


def _bounded_hook_assets(root):
    """Exact B templates: explicit sync can upgrade these without taking custom assets."""
    from cli.product_bookends import hook_script
    return {".cursor/hooks/session-start-next.sh": hook_script(root),
            ".cursor/hooks/session-end-closeout.sh": hook_script(root),
            ".cursor/hooks.json": (json.dumps({"version": 1, "hooks": {
                "sessionStart": [{"command": str(root / ".cursor/hooks/session-start-next.sh")}],
                "stop": [{"command": str(root / ".cursor/hooks/session-end-closeout.sh")}],
            }}, indent=2) + "\n").encode()}


def classify_assets(root, mapping, config):
    """D's three-way classification, with confined reads and preserved origins.

    Full legacy footprint rows remain visible; this wave only updates its
    explicitly requested launcher/bookend assets. Unknown assets stay owned by
    the repository. Living documents are never update candidates here.
    """
    entries = _lock_entries(root)
    bounded_hooks = _bounded_hook_assets(root) if any(path in HOOKS for path in mapping) else {}
    rows = []
    for path, body in sorted(mapping.items()):
        old = read(root, path, missing=True)
        entry = entries.get(path, {})
        baseline = entry.get("sha256", "").removeprefix("sha256:")
        current = "absent" if old is None else digest(old)
        after = digest(body)
        if old is None:
            classification = "missing"
        elif entry.get("origin") == "preserved":
            classification = "preserved"
        elif old == body:
            classification = "unchanged"
        elif (current == baseline or (path == LAUNCHER and _bound_launcher(old, root, config))
              or (path in bounded_hooks and old == bounded_hooks[path])):
            classification = "kit-updated"
        elif after == baseline:
            classification = "consumer-modified"
        else:
            classification = "both-changed"
        rows.append({"path": path, "classification": classification,
                     "origin": entry.get("origin", "unrecorded"),
                     "before": current, "after": after})
    return rows


def _document_paths(config):
    base = config["repo"].get("root_relative_docs", "docs")
    docs = config.get("docs", {})
    paths = {NEXT}
    for field in ("handover", "roadmap", "coordination", "standing_decisions"):
        if docs.get(field):
            paths.add((Path(base) / docs[field]).as_posix())
    for lane in (docs.get("lanes") or {}).values():
        for field in ("handover", "roadmap"):
            if lane.get(field):
                paths.add((Path(base) / lane[field]).as_posix())
    return paths


def inventory(root, config):
    paths = _document_paths(config) | set(_lock_entries(root)) | {LOCK, ".overseer/ledger.jsonl"}
    for section, fields in {
        "checkpoints": ("policy", "active_manifest", "progress", "orchestrator"),
        "honesty": ("ledger", "roles_file", "ci_reexecutor"),
        "model_routing": ("policy",), "workspace": ("manifest",),
        "close_ritual": ("consumer_verify_script",),
    }.items():
        values = config.get(section) or {}
        for field in fields:
            if values.get(field):
                paths.add(values[field])
    for extension in config.get("extensions") or []:
        paths.add(extension["config_path"])
    for path in (config.get("close_ritual") or {}).get("require_paths") or []:
        target = root / path
        if target.is_dir() and not target.is_symlink():
            for parent, dirs, files in os.walk(target, followlinks=False):
                if any((Path(parent) / name).is_symlink() for name in dirs):
                    raise Refusal("path_symlink")
                paths.update((Path(parent) / name).relative_to(root).as_posix() for name in files)
        else:
            paths.add(path)
    # Inventory custom policy, rule and skill files, including unrecorded ones.
    for prefix in (".overseer/policy", ".cursor/rules", ".cursor/skills", ".claude/skills"):
        directory = root / prefix
        if directory.is_symlink():
            raise Refusal("path_symlink")
        if directory.exists():
            for parent, dirs, files in os.walk(directory, followlinks=False):
                for name in dirs:
                    if (Path(parent) / name).is_symlink():
                        raise Refusal("path_symlink")
                paths.update((Path(parent) / name).relative_to(root).as_posix() for name in files)
    return [_snapshot(root, path) for path in sorted(paths)]


def _legacy_drafts(root, config):
    """Migration-only extraction: proposals are never published or executed."""
    drafts = []
    for path in sorted(_document_paths(config) - {NEXT}):
        body = read(root, path, missing=True)
        if body is None:
            continue
        try:
            text = body.decode("utf-8")
        except UnicodeError:
            raise Refusal("living_document_encoding_invalid") from None
        pattern = r"(?m)^### Paste-ready prompt[^\n]*\n(?:\s*\n)*(`{3,}|~{3,})[^\n]*\n(.*?)^\1[ \t]*$"
        for match in re.finditer(pattern, text, re.DOTALL | re.MULTILINE):
            drafts.append({"source": path, "text": match.group(2),
                           "sha256": digest(match.group(2).encode()),
                           "publication": "operator acceptance and next-write --expect-next absent required"})
    if read(root, NEXT, missing=True) is None and len({d["sha256"] for d in drafts}) > 1:
        raise Refusal("conflicting_legacy_prompts")
    return drafts


def _context(root):
    from cli import v1
    from cli.product_config import normalize
    config = normalize(read(root, CONFIG), root=root).data
    if config['vcs']['canonical'] == 'muse':
        state = v1.revision(root, config)
        return {'root': str(root), 'branch': state.branch, 'head': state.head,
                'source_id': state.source_id, 'runtime': v1.runtime()}
    if Path(v1.git(root, 'rev-parse', '--show-toplevel')).resolve(strict=True) != root:
        raise Refusal('migration_context_changed')
    return {"root": str(root), "branch": v1.branch(root), "head": v1.head(root),
            "runtime": v1.runtime()}


def _check_context(root, captured, allowed_config):
    from cli import v1
    if (root.resolve(strict=True) != root or
            _context(root) != captured):
        raise Refusal("migration_context_changed")
    if digest(read(root, CONFIG)) not in allowed_config:
        raise Refusal("migration_config_changed")


def _updates(root, mapping):
    updates = []
    for path, data in mapping.items():
        before = _snapshot(root, path)
        mode = (before["mode"] if path in (CONFIG, ".gitignore", ".museignore") and before["mode"] is not None else
                0o755 if path.endswith(".sh") or path.endswith("/ok") else 0o644)
        if before["sha256"] != digest(data) or before["mode"] != mode:
            updates.append({"path": path, "before": before, "after": digest(data),
                            "mode": mode, "content_b64": base64.b64encode(data).decode()})
    return updates


def apply_mapping(root, mapping, *, check_context, dry_run=False):
    """Preflight all targets before taking the same directory lock as migration."""
    updates = _updates(root, mapping)
    if dry_run:
        return [row["path"] for row in updates]
    fd = os.open(root / ".overseer", os.O_RDONLY | os.O_DIRECTORY | os.O_NOFOLLOW)
    try:
        fcntl.flock(fd, fcntl.LOCK_EX)
        check_context()
        for row in updates:
            if not _same(root, row["before"]):
                raise Refusal("stale_write: " + row["path"])
        for row in updates:
            atomic(root, row["path"], base64.b64decode(row["content_b64"]),
                   expected=row["before"]["sha256"], mode=row["mode"], before_replace=check_context)
    except (Refusal, OSError) as exc:
        completed = [row["path"] for row in updates if _snapshot(root, row["path"]) ==
                     {"path": row["path"], "sha256": row["after"], "mode": row["mode"]}]
        if completed:
            reason = str(exc) if isinstance(exc, Refusal) else type(exc).__name__
            raise Refusal("partial_asset_update: " + ",".join(completed) + "; " + reason +
                          "; config is last; rerun explicit sync after resolving drift") from exc
        raise
    finally:
        os.close(fd)
    return [row["path"] for row in updates]


def build_plan(root, args):
    from cli import v1
    from cli.product_config import normalize
    original = read(root, CONFIG)
    # Stable proposed UUID makes repeated dry runs reviewable. It is persisted
    # only by the explicitly accepted initialization/migration plan.
    proposed = str(uuid.uuid5(uuid.NAMESPACE_URL, str(root) + ":" + digest(original)))
    unbound = normalize(original, root=root, runtime=v1.runtime())
    identity = unbound.data["repo"].get("id") or proposed
    model = normalize(original, root=root, runtime=v1.runtime(), bind=True, identity=identity,
                      lane=getattr(args, "lane", None), model=getattr(args, "model", None))
    config = copy.deepcopy(model.data)
    if getattr(args, "repo_name", None) not in (None, config["repo"]["name"]):
        raise Refusal("migration_repo_name_change_requires_explicit_resolution")
    if getattr(args, "regime", None) not in (None, config["vcs"]["regime"]):
        raise Refusal("authority_change_requires_adopt")
    if getattr(args, "refresh_runtime", False):
        config["runtime"] = v1.runtime()
    if getattr(args, "bound_id", None) not in (None, identity):
        raise Refusal("launcher_identity_mismatch")
    launcher = read(root, LAUNCHER, missing=True)
    if launcher is not None and not _bound_launcher(launcher, root, config):
        raise Refusal("migration_launcher_binding_conflict")
    # Preserve the selected authority and verify its native binding when available.
    git_authority = config["vcs"]["canonical"] == "git"
    current_next = read(root, NEXT, missing=True)
    available = git_authority or bool(config['vcs']['muse'].get('binding'))
    if available and current_next is not None:
        observed = v1.capture_context(root, original, config)
        for lane in config['docs']['lanes']:
            # A missing lane is visible at read time, and is not invented by migration.
            meta, body = v1.parse_next(current_next)
            if (meta['schema'] == 3 and lane not in meta['entries']) or (meta['schema'] != 3 and meta['lane'] != lane):
                continue
            v1.validate_next(root, config, current_next, Namespace(lane=lane), context=observed, freshness=False)
    mapping = v1.assets(root, config, False) if available else {}
    if getattr(args, "hooks", False):
        raise Refusal("migration_does_not_install_existing_repository_hooks")
    mapping[CONFIG] = v1.encode(config)
    updates = _updates(root, mapping)
    updated_paths = {row["path"] for row in updates}
    classifications = classify_assets(root, {k: v for k, v in mapping.items() if k != CONFIG}, config)
    for row in classifications:
        if row["classification"] == "preserved" and row["path"] in updated_paths:
            raise Refusal("migration_preserved_asset_requires_resolution: " + row["path"])
    protected_map = {row["path"]: row for row in inventory(root, config)}
    protected_map.update({path: _snapshot(root, path) for path in mapping if path not in updated_paths})
    protected = [row for path, row in sorted(protected_map.items()) if path not in updated_paths]
    plan = {"plan_version": 1, "operation": "schema-3-migration", "source_schema": model.source_schema,
            "repository": config["repo"], "source_config_sha256": digest(original),
            "normalized_config": config, "field_map": model.field_map,
            "diagnostics": list(model.diagnostics), "refresh_runtime": bool(getattr(args, "refresh_runtime", False)),
            "context": _context(root) if available else {"root": str(root), "runtime": v1.runtime(),
                "authority": "muse", "unavailable": "muse_binding_required"},
            "assets": updates, "protected": protected,
            "classification": classifications,
            "legacy_prompt_drafts": _legacy_drafts(root, config),
            "next": "preserved byte-for-byte; accepted drafts publish only through next-write",
            "apply_supported": available and config["runtime"] == v1.runtime()}
    if not available:
        plan['diagnostics'].append('Muse authority preserved; apply requires explicit native binding')
    if config["runtime"] != v1.runtime():
        plan["diagnostics"].append("Runtime changed: repeat dry-run with explicit --refresh-runtime")
    return plan


def _apply_plan(root, args, plan):
    from cli import v1
    from cli.product_config import normalize
    _plan_shape(plan)
    expected_plan = getattr(args, "expect_plan", None)
    if expected_plan != digest(_json(plan)):
        raise Refusal("migration_plan_digest_mismatch")
    if getattr(args, "expect_config", None) != plan.get("source_config_sha256"):
        raise Refusal("migration_expected_config_mismatch")
    if plan.get("plan_version") != 1 or plan.get("operation") != "schema-3-migration":
        raise Refusal("migration_plan_invalid")
    if plan.get("context", {}).get("root") != str(root):
        raise Refusal("migration_repository_mismatch")
    if not plan.get("apply_supported"):
        raise Refusal("migration_apply_unavailable: review plan diagnostics")
    backup = ".overseer/migrations/" + expected_plan
    original = read(root, CONFIG)
    resume = bool(getattr(args, "resume", False))
    if resume:
        saved = read(root, backup + "/files/" + CONFIG, missing=True)
        if saved is not None:
            original = saved
    if digest(original) != plan["source_config_sha256"]:
        raise Refusal("stale_write: " + CONFIG)
    target = plan["normalized_config"]
    validated = normalize(v1.encode(target), root=root, runtime=v1.runtime())
    if not validated.bound or target.get("schema") != 3 or validated.data != target:
        raise Refusal("migration_config_plan_invalid")
    proposed = normalize(original, root=root, runtime=v1.runtime(), bind=True,
                         identity=target["repo"]["id"], lane=target["context"]["lane"],
                         model=target["context"]["model"]).data
    if plan["refresh_runtime"]:
        proposed["runtime"] = v1.runtime()
    if proposed != target or target["runtime"] != v1.runtime():
        raise Refusal("migration_config_plan_changed")
    # JSON object order is not part of a reviewed plan's canonical digest.
    # Reproduce target YAML from the preserved source rather than an incidental
    # order chosen by a JSON viewer/editor.
    target = proposed
    if getattr(args, "bound_id", None) not in (None, target["repo"]["id"]):
        raise Refusal("launcher_identity_mismatch")
    approved = dict(v1.assets(root, target, False), **{CONFIG: v1.encode(target)})
    rows = plan["assets"]
    if not isinstance(rows, list) or len({row["path"] for row in rows}) != len(rows):
        raise Refusal("migration_asset_plan_invalid")
    for row in rows:
        if (row["path"] not in approved or row["before"]["path"] != row["path"] or
                base64.b64decode(row["content_b64"], validate=True) != approved[row["path"]] or
                row["after"] != digest(approved[row["path"]]) or
                row["mode"] != (row['before']['mode'] if row['path'] in (CONFIG, '.gitignore', '.museignore') and row['before']['mode'] is not None else
                                0o755 if row['path'].endswith(('.sh', '/ok')) else 0o644)):
            raise Refusal("migration_asset_plan_changed")
    for path, content in approved.items():
        if path not in {row["path"] for row in rows}:
            captured = next((row for row in plan["protected"] if row["path"] == path), None)
            if captured is None or captured["sha256"] != digest(content) or not _same(root, captured):
                raise Refusal("migration_asset_plan_incomplete")
    if any(row["path"] == CONFIG for row in rows) and rows[-1]["path"] != CONFIG:
        raise Refusal("migration_config_must_be_last")
    allowed = {plan["source_config_sha256"]}
    if resume:
        allowed.add(digest(v1.encode(target)))

    def check():
        _check_context(root, plan["context"], allowed)
        for entry in plan["protected"]:
            if not _same(root, entry):
                raise Refusal("migration_protected_asset_changed: " + entry["path"])

    # No parent creation occurs until all destination and backup checks pass.
    for row in rows:
        current = _snapshot(root, row["path"])
        after = {"path": row["path"], "sha256": row["after"], "mode": row["mode"]}
        if current != row["before"] and not (resume and current == after):
            raise Refusal("stale_write: " + row["path"])
        confined(root, backup + "/files/" + row["path"], missing_parents=True)
    manifest_path = backup + "/manifest.json"
    manifest = _json({"plan_sha256": expected_plan, "plan": plan,
                      "rollback": "Quiesce commands; restore each files/ entry with its recorded mode; remove only originally absent assets; restore config last.",
                      "per_file_atomic_only": True})
    existing_manifest = read(root, manifest_path, missing=True)
    if existing_manifest is not None and existing_manifest != manifest:
        raise Refusal("migration_backup_manifest_mismatch")
    backup_rows = list(rows)
    if CONFIG not in {row["path"] for row in rows}:
        backup_rows.append({"path": CONFIG, "before": _snapshot(root, CONFIG)})
    backups = {}
    for row in backup_rows:
        if row["before"]["sha256"] == "absent":
            continue
        path = backup + "/files/" + row["path"]
        saved = read(root, path, missing=True)
        data = original if row["path"] == CONFIG else read(root, row["path"])
        if saved is not None:
            data = saved
        if digest(data) != row["before"]["sha256"]:
            raise Refusal("migration_backup_missing_original: " + row["path"])
        if saved is not None and digest(saved) != row["before"]["sha256"]:
            raise Refusal("migration_backup_mismatch")
        backups[path] = (data, row["before"]["mode"])
    check()
    changed = []
    fd = os.open(root / ".overseer", os.O_RDONLY | os.O_DIRECTORY | os.O_NOFOLLOW)
    try:
        fcntl.flock(fd, fcntl.LOCK_EX)
        check()
        for row in rows:
            current = _snapshot(root, row["path"])
            after = {"path": row["path"], "sha256": row["after"], "mode": row["mode"]}
            if current != row["before"] and not (resume and current == after):
                raise Refusal("stale_write: " + row["path"])
        for path, (data, mode) in backups.items():
            saved = read(root, path, missing=True)
            atomic(root, path, data, expected="absent" if saved is None else digest(saved),
                   mode=mode, before_replace=check)
        atomic(root, manifest_path, manifest,
               expected="absent" if existing_manifest is None else digest(existing_manifest),
               before_replace=check)
        for row in rows:
            current = _snapshot(root, row["path"])
            after = {"path": row["path"], "sha256": row["after"], "mode": row["mode"]}
            if current == after:
                continue
            atomic(root, row["path"], approved[row["path"]], expected=row["before"]["sha256"],
                   mode=row["mode"], before_replace=check)
            changed.append(row["path"])
        allowed.add(digest(v1.encode(target)))
        check()
    except (Refusal, OSError) as exc:
        completed = [row["path"] for row in rows
                     if _snapshot(root, row["path"]) == {"path": row["path"], "sha256": row["after"], "mode": row["mode"]}]
        return {"ok": False, "partial": bool(completed), "completed": completed,
                "error": str(exc) if isinstance(exc, Refusal) else type(exc).__name__,
                "backup": backup, "resume": "Repeat the same --apply-plan, --expect-plan and --expect-config with --resume; drift still refuses"}
    finally:
        os.close(fd)
    return {"ok": True, "migrated": True, "changed": changed, "backup": backup,
            "repository": target["repo"], "config_sha256": digest(v1.encode(target)),
            "next": "preserved", "resumed": resume}


def migrate(root, args):
    if bool(getattr(args, "dry_run", False)) == bool(getattr(args, "apply_plan", None)):
        raise Refusal("migration_requires_dry_run_or_apply_plan")
    if args.dry_run:
        plan = build_plan(root, args)
        return {"ok": True, "dry_run": True, "plan_sha256": digest(_json(plan)), "plan": plan}
    def unique(pairs):
        result = {}
        for key, value in pairs:
            if key in result:
                raise Refusal("migration_plan_duplicate_key")
            result[key] = value
        return result

    def invalid_constant(value):
        raise Refusal("migration_plan_invalid_constant")

    try:
        wrapper = json.loads(read(root, args.apply_plan).decode("utf-8"),
                             object_pairs_hook=unique, parse_constant=invalid_constant)
    except (json.JSONDecodeError, UnicodeError) as exc:
        raise Refusal("migration_plan_json_invalid") from exc
    except RecursionError as exc:
        raise Refusal("migration_plan_nesting_invalid") from exc
    if not isinstance(wrapper, dict):
        raise Refusal("migration_plan_invalid")
    plan = wrapper.get("plan", wrapper)
    return _apply_plan(root, args, plan)


def sync(root, config, original, args):
    from cli import v1
    captured = v1.capture_context(root, original, config)
    runtime_observed = v1.runtime()
    updated = copy.deepcopy(config)
    updated["runtime"] = v1.runtime()
    mapping = v1.assets(root, updated, bool(getattr(args, "hooks", False)))
    selected = getattr(args, "only", None)
    if selected:
        selectors = [selected] if isinstance(selected, str) else selected
        # Discover only the foundation resources implemented in this wave.
        # Matching a hook destination is not permission to install its hook.
        available = v1.assets(root, updated, True)
        aliases = {"launcher": {LAUNCHER}, "hooks": set(HOOKS)}
        wanted = set()
        for selector in selectors:
            matches = aliases.get(selector)
            if matches is None:
                matches = {path for path in available if fnmatch.fnmatchcase(path, selector)}
            if not matches:
                raise Refusal("sync_only_no_matches: " + selector)
            if matches.intersection(HOOKS) and not getattr(args, "hooks", False):
                raise Refusal("sync_hooks_requires_explicit_hooks")
            wanted.update(matches)
        mapping = {path: body for path, body in available.items() if path in wanted}
    rows = classify_assets(root, mapping, config)
    preserved = []
    for row in rows:
        if row["classification"] in ("preserved", "consumer-modified", "both-changed"):
            if row["classification"] != "preserved" and not getattr(args, "preserve_modified", False):
                raise Refusal("sync_asset_modified: " + row["path"])
            preserved.append(row["path"])
            mapping.pop(row["path"], None)
    from cli.product_footprint import with_lock
    mapping = with_lock(root, mapping, updated, preserved=preserved)
    # Keep compatibility config bytes unless refresh is actually required; a
    # schema upgrade is explicit migration, never an incidental sync side effect.
    source = v1.decode(original)
    source["runtime"] = updated["runtime"]
    if source["runtime"] != v1.decode(original)["runtime"]:
        mapping[CONFIG] = v1.encode(source)
    changing = {row["path"] for row in _updates(root, mapping)}
    protected_map = {row["path"]: row for row in inventory(root, config)}
    protected_map.update({path: _snapshot(root, path) for path in mapping if path not in changing})
    protected = [row for path, row in protected_map.items() if path not in changing]

    def check():
        if (read(root, CONFIG) != original or v1.capture_context(root, original, config) != captured
                or v1.runtime() != runtime_observed):
            raise Refusal('sync_context_changed')
        for row in protected:
            if not _same(root, row):
                raise Refusal("sync_protected_asset_changed: " + row["path"])

    differences = {}
    if getattr(args, "diff", False):
        for path, body in mapping.items():
            prior = read(root, path, missing=True) or b""
            differences[path] = "".join(difflib.unified_diff(prior.decode().splitlines(True),
                body.decode().splitlines(True), fromfile=path, tofile=path + " (planned)"))
    changed = apply_mapping(root, mapping, check_context=check, dry_run=bool(args.dry_run))
    return {"ok": True, "repository": config["repo"], "changed": changed,
            "classification": rows, "preserved": preserved, "dry_run": bool(args.dry_run),
            "diff": differences, "next": "preserved"}

"""Repository-bound context and the single confined canonical NEXT writer."""
from __future__ import annotations

import argparse
import fcntl
import json
import os
from pathlib import Path
import re
import shlex
import stat
import subprocess
import sys
import uuid

import yaml

from cli.v1_io import LIMIT, Refusal, atomic, confined, digest, read
from cli.v1_revision import revision
from cli.v1_policy import local_path

VERSION = "1.0.0.dev1"
KIT = Path(__file__).resolve().parent.parent
CONFIG = ".overseer/config.yaml"
NEXT = "docs/NEXT.md"
KINDS = ("plan", "implement", "review", "maintain", "stop")
TOKEN = re.compile(r"[A-Za-z0-9][A-Za-z0-9_.-]{0,127}\Z")
def runtime_files():
    """Owned code/resources used by normalization, migration and bound assets.

    Include complete cli/adapter source families so lazy helpers cannot escape
    the binding. Optional hosted configuration validators do not load transports.
    Paths and bytes both participate; adding or removing a source changes it.
    """
    paths = {"VERSION", "cli/ok", "cli/overseer", "scripts/muse-bridge-deploy.sh"}
    for directory in ("cli", "adapters", "tools"):
        paths.update(p.relative_to(KIT).as_posix() for p in (KIT / directory).rglob("*.py"))
    paths.update("tools/hosted_dashboard/" + p for p in
                 ("__init__.py", "config.py", "hosts.py", "validators.py"))
    for directory in ("cursor", "templates", "policy", "tools/app/static", "tools/hosted_dashboard/static"):
        paths.update(p.relative_to(KIT).as_posix() for p in (KIT / directory).rglob("*")
                     if p.is_file() and "__pycache__" not in p.parts)
    return tuple(sorted(paths))


RUNTIME_FILES = runtime_files()


class UniqueLoader(yaml.SafeLoader):
    pass


def unique_mapping(loader, node):
    result = {}
    for key_node, value_node in node.value:
        key = loader.construct_object(key_node)
        if not isinstance(key, str) or key in result:
            raise Refusal("duplicate_or_invalid_key")
        result[key] = loader.construct_object(value_node)
    return result


UniqueLoader.add_constructor(yaml.resolver.BaseResolver.DEFAULT_MAPPING_TAG, unique_mapping)


def decode(data: bytes):
    try:
        return yaml.load(data.decode("utf-8"), Loader=UniqueLoader)
    except (UnicodeError, yaml.YAMLError, ValueError, TypeError) as exc:
        raise Refusal("malformed_document") from exc


def encode(value) -> bytes:
    return yaml.safe_dump(value, sort_keys=False, allow_unicode=True).encode()


def keys(value, required):
    if not isinstance(value, dict) or set(value) != set(required):
        raise Refusal("schema_keys_invalid")


def label(value):
    if not isinstance(value, str) or not value.strip() or len(value) > 200 or any(ord(c) < 32 for c in value):
        raise Refusal("label_invalid")
    return value


def token(value):
    if not isinstance(value, str) or not TOKEN.fullmatch(value):
        raise Refusal("identifier_invalid")
    return value


def git(root: Path, *args: str, optional: bool = False, raw: bool = False):
    env = {k: v for k, v in os.environ.items() if not k.startswith("GIT_")}
    env.update(PATH="/usr/bin:/bin", GIT_OPTIONAL_LOCKS="0", GIT_CONFIG_NOSYSTEM="1",
               GIT_CONFIG_GLOBAL="/dev/null", LC_ALL="C")
    proc = subprocess.run(["/usr/bin/git", "-c", "core.fsmonitor=false", "-c",
                           "core.hooksPath=/dev/null", "-C", str(root), *args],
                          env=env, capture_output=True, text=not raw, timeout=15)
    if proc.returncode and not optional:
        raise Refusal("git_read_failed: " + args[0])
    if raw:
        return proc.stdout if proc.returncode == 0 else b""
    return proc.stdout.strip() if proc.returncode == 0 else ""


def root_for(args) -> Path:
    cwd = Path.cwd().resolve()
    requested = Path(args.repo).expanduser().resolve(strict=True) if args.repo else cwd
    # A configured Muse/legacy root can be inspected without probing Git.
    # Never walk beyond the nearest repository boundary into a parent checkout.
    selected = requested
    if not args.repo:
        while not (selected / CONFIG).exists():
            if (selected / ".git").exists() or (selected / ".muse").exists() or selected == selected.parent:
                break
            selected = selected.parent
    if (selected / CONFIG).exists() or (selected / CONFIG).is_symlink():
        root = selected
    else:
        from cli.v1_revision import discover
        root = discover(requested)
    if args.repo and requested != root:
        raise Refusal("explicit_repo_must_be_root")
    if args.bound_root and root != Path(args.bound_root):
        raise Refusal("launcher_repository_mismatch")
    if args.binding_path:
        path = Path(os.path.abspath(args.binding_path))
        if path.is_symlink() or path != root / ".overseer/bin/ok":
            raise Refusal("launcher_location_mismatch")
    if bool(args.bound_root) != bool(args.bound_id) or bool(args.bound_root) != bool(args.binding_path):
        raise Refusal("launcher_binding_incomplete")
    if args.config:
        path = Path(args.config)
        if not path.is_absolute():
            path = root / path
        if path != root / CONFIG:
            raise Refusal("only_canonical_config_supported")
    return root


def branch(root):
    value = git(root, "symbolic-ref", "--quiet", "--short", "HEAD", optional=True)
    if not value:
        raise Refusal("detached_head")
    return label(value)


def head(root):
    return git(root, "rev-parse", "--verify", "HEAD", optional=True) or "unborn"


def runtime():
    if (KIT / "VERSION").read_text().strip() != VERSION:
        raise Refusal("runtime_version_mismatch")
    data = b"".join(p.encode() + b"\0" + confined(KIT, p).read_bytes() + b"\0"
                    for p in runtime_files())
    return {"root": str(KIT), "version": VERSION, "sha256": digest(data)}


def config_for(root, args, *, syncing=False, authority=True):
    from cli.product_config import normalize
    data = read(root, CONFIG)
    normalized = normalize(data, root=root)
    config = normalized.data
    if not normalized.bound:
        raise Refusal("configuration_unbound: inspect with status; use init --migrate")
    repo = config["repo"]
    if repo["root"] != str(root):
        raise Refusal("config_repository_mismatch")
    if getattr(args, "bound_id", None) and repo["id"] != args.bound_id:
        raise Refusal("launcher_identity_mismatch")
    if config["runtime"]["root"] != str(KIT):
        raise Refusal("runtime_installation_mismatch")
    if not syncing and config["runtime"] != runtime():
        raise Refusal("runtime_changed: run this installation's explicit sync")
    if authority:
        revision(root, config)
    return config, data


def capture_context(root, config_data, config=None):
    from cli.product_config import normalize
    config = config or (normalize(config_data, root=root).data if config_data else None)
    if config is None or config['vcs']['canonical'] == 'git':
        if Path(git(root, 'rev-parse', '--show-toplevel')).resolve(strict=True) != root:
            raise Refusal('repository_context_changed')
        return {"config": config_data, "branch": branch(root), "head": head(root),
                "vcs": "git", "source_id": None}
    state = revision(root, config)
    return {"config": config_data, "branch": state.branch, "head": state.head,
            "vcs": state.kind, "source_id": state.source_id}


def check_context(root, config, args, captured):
    """Refuse a changed observation; never rebase a prepared prompt implicitly."""
    if root.resolve(strict=True) != root:
        raise Refusal("repository_context_changed")
    current, data = config_for(root, args)
    if current != config or data != captured["config"]:
        raise Refusal("config_context_changed")
    if capture_context(root, data, current) != captured:
        raise Refusal("repository_context_changed")


def check_expectations(meta, args):
    for field in ("repo_id", "branch", "lane", "model", "action_id", "action_kind"):
        expected = getattr(args, field, None)
        if expected is not None and meta[field] != expected:
            raise Refusal("expected_" + field + "_mismatch")


def parse_next(data):
    from cli.product_next import parse_collection
    collection = parse_collection(data)
    if collection is not None:
        return collection
    try:
        text = data.decode("utf-8")
    except UnicodeError:
        raise Refusal("next_encoding_invalid") from None
    if not text.startswith("---\n") or "\r" in text:
        raise Refusal("next_frontmatter_invalid")
    parts = text[4:].split("\n---\n", 1)
    if len(parts) != 2:
        raise Refusal("next_frontmatter_invalid")
    meta = decode(parts[0].encode())
    prompt = parts[1]
    if not isinstance(meta, dict):
        raise Refusal("schema_keys_invalid")
    extra = ("vcs", "source_id") if meta.get("schema") == 2 else ()
    keys(meta, ("schema", "repo_id", "repo_root", "branch", "base_head", "lane",
                "model", "action_id", "action_kind", "prompt_sha256", *extra))
    if type(meta["schema"]) is not int or meta["schema"] not in (1, 2):
        raise Refusal("next_version_invalid")
    if extra and (meta["vcs"] not in ("git", "muse") or
                  (meta["vcs"] == "git" and meta["source_id"] is not None)):
        raise Refusal("next_revision_kind_invalid")
    for field in ("repo_id", "repo_root", "branch", "base_head", "model"):
        label(meta[field])
    token(meta["lane"])
    token(meta["action_id"])
    if meta["action_kind"] not in KINDS:
        raise Refusal("action_kind_invalid")
    validate_prompt(prompt)
    if meta["prompt_sha256"] != digest(prompt.encode()):
        raise Refusal("prompt_digest_mismatch")
    return meta, prompt


def validate_prompt(prompt):
    if not prompt.strip() or len(prompt.encode()) > 64000 or any(
        (ord(c) < 32 and c not in "\n\t") or ord(c) == 127 for c in prompt
    ):
        raise Refusal("prompt_invalid")
    # Binding lines are generated from metadata, never trusted from prose.
    if re.search(r"(?im)^\s*(repo(?:sitory)?(?: id| root)?|branch|lane|model|action id|action kind|step)\s*:", prompt):
        raise Refusal("prompt_contains_binding_fields")


def validate_next(root, config, data, args, *, context, freshness=True):
    from cli.product_next import selected_entry, selected_lane
    meta, prompt = parse_next(data)
    meta, prompt = selected_entry(meta, prompt, config, args)
    authority = config['vcs']['canonical']
    if meta.get("vcs", "git") != authority or meta.get('source_id') != context.get('source_id'):
        raise Refusal('next_authority_or_source_mismatch')
    for field, expected in {"repo_id": config["repo"]["id"], "repo_root": str(root),
                            "branch": context["branch"], 'lane': selected_lane(config, args)}.items():
        if meta[field] != expected:
            raise Refusal("next_" + field + "_mismatch")
    if len(config['docs']['lanes']) == 1 and meta['model'] != config['context']['model']:
        raise Refusal('next_model_mismatch')
    check_expectations(meta, args)
    if getattr(args, "expect_next", None) and args.expect_next != digest(data):
        raise Refusal("next_digest_mismatch")
    current = context["head"]
    if freshness and current != meta["base_head"]:
        if authority == 'muse':
            raise Refusal('next_stale_head')
        # Permit the one closing commit that publishes these exact NEXT bytes.
        # Any subsequent commit needs an explicit refresh through next-write.
        if current == "unborn":
            raise Refusal("next_stale_head")
        parents = git(root, "rev-list", "--parents", "-n", "1", current).split()[1:]
        expected_parents = [] if meta["base_head"] == "unborn" else [meta["base_head"]]
        committed = git(root, "show", current + ":" + NEXT, optional=True, raw=True)
        if parents != expected_parents or committed != data:
            raise Refusal("next_stale_head")
        if meta['schema'] == 3 and parents:
            previous = git(root, 'show', parents[0] + ':' + NEXT, optional=True, raw=True)
            if previous:
                old_meta, old_body = parse_next(previous)
                try:
                    old_meta, old_body = selected_entry(old_meta, old_body, config, args)
                except Refusal:
                    old_meta = {}
                if all(old_meta.get(k) == meta[k] for k in
                       ('branch', 'base_head', 'model', 'action_id', 'action_kind', 'prompt_sha256')):
                    raise Refusal('next_stale_head: lane not published by closing commit')
    return meta, prompt


def rendered(meta, prompt):
    binding = (f"Repository: {meta['repo_root']}\nRepository ID: {meta['repo_id']}\n"
               f"Branch: {meta['branch']}\nLane: {meta['lane']}\nModel: {meta['model']}\n"
               f"Action ID: {meta['action_id']}\nAction kind: {meta['action_kind']}\n")
    body = binding + "\n" + prompt.rstrip() + "\n"
    fence = "`" * max(3, 1 + max((len(x) for x in re.findall(r"`+", body)), default=0))
    return "## CURRENT NEXT — paste this\n\n" + fence + "text\n" + body + fence + "\n"


def write_next(root, config, args, prompt, *, expected, context):
    if getattr(args, 'batch_file', None):
        from cli.product_next import batch_publication
        payload = batch_publication(root, config, args, expected, context)
    else:
        from cli.product_next import selected_lane, publication
        lane = selected_lane(config, args)
        meta = {"schema": 1, "repo_id": config["repo"]["id"], "repo_root": str(root),
                "branch": context["branch"], "base_head": context["head"],
                'lane': lane, 'model': getattr(args, 'model', None) or config['context']['model'],
                "action_id": args.action_id, "action_kind": args.action_kind,
                "prompt_sha256": digest(prompt.encode())}
        if context.get('vcs') == 'muse':
            meta.update(schema=2, vcs='muse', source_id=context['source_id'])
            if getattr(args, 'vcs', None) != 'muse' or getattr(args, 'base_head', None) != context['head']:
                raise Refusal('muse_writer_requires_explicit_vcs_and_base_head')
        if getattr(args, 'vcs', None) not in (None, context.get('vcs', 'git')):
            raise Refusal('expected_vcs_mismatch')
        if getattr(args, 'base_head', None) not in (None, context['head']):
            raise Refusal('expected_base_head_mismatch')
        check_expectations(meta, args)
        payload = publication(root, config, meta, prompt, expected, reset=getattr(args, 'reset_authority', False))
        validate_next(root, config, payload, args, context=context, freshness=False)
    check_context(root, config, args, context)
    path = confined(root, NEXT, parents=True)
    # Advisory directory lock avoids ordinary concurrent lost updates without
    # persistent lock state or a recovery protocol.
    fd = os.open(path.parent, os.O_RDONLY | os.O_DIRECTORY | os.O_NOFOLLOW)
    try:
        fcntl.flock(fd, fcntl.LOCK_EX)
        check_context(root, config, args, context)
        atomic(root, NEXT, payload, expected=expected,
               before_replace=lambda: check_context(root, config, args, context))
    finally:
        os.close(fd)
    return payload


def launcher(root, identity):
    q = shlex.quote
    return ("#!/bin/sh\nset -eu\nPATH=/usr/bin:/bin\nexport PATH\n"
            "unset PYTHONPATH PYTHONHOME VIRTUAL_ENV\nexec "
            + q(str(KIT / ".venv/bin/python3")) + " -I -B " + q(str(KIT / "cli/bootstrap.py"))
            + " --bound-root " + q(str(root)) + " --bound-id " + q(identity)
            + ' --binding-path "$0" "$@"\n').encode()


def hook_script(root):
    from cli.product_bookends import hook_script as render_hook
    return render_hook(root)


def assets(root, config, hooks=False):
    result = {".overseer/bin/ok": launcher(root, config["repo"]["id"])}
    if hooks:
        from cli.product_bookends import cursor_assets, instruction_assets
        result.update(cursor_assets(root))
        result.update(instruction_assets(root))
    from cli.product_config import normalize
    from cli.footprint import resolve_footprint
    from cli.product_migration import _document_paths
    model = normalize(encode(config), root=root)
    living = _document_paths(config)
    for item in resolve_footprint(model.adapter, kit=KIT):
        if item.destination not in living and not item.destination.startswith('.cursor/hooks'):
            result[item.destination] = item.content
    result['policy/model-routing.yaml'] = (KIT / 'policy/model-routing.yaml').read_bytes()
    return result


def apply_assets(root, mapping, *, dry_run=False):
    updates = []
    # Validate all destinations before the first replacement.
    for path, data in mapping.items():
        target = confined(root, path, parents=not dry_run, missing_parents=dry_run)
        old = read(root, path, missing=True)
        mode = 0o755 if path.endswith(".sh") or path.endswith("/ok") else 0o644
        if old != data or (old is not None and stat.S_IMODE(target.stat().st_mode) != mode):
            updates.append((path, data, "absent" if old is None else digest(old), mode))
    if not dry_run:
        for path, data, expected, mode in updates:
            atomic(root, path, data, expected=expected, mode=mode)
    return [p for p, _, _, _ in updates]


def initialize(root, args):
    from cli.product_config import normalize
    from cli.product_migration import apply_mapping, classify_assets, _snapshot, _same, LAUNCHER, HOOKS
    from cli.product_authority import select, bind_muse, tracked_bindings
    from cli.v1_policy import ignore_assets
    existing = read(root, CONFIG, missing=True)
    if existing is not None:
        config, _ = config_for(root, args)
        if select(root, args, config) != config['vcs']['canonical'] or getattr(args, 'muse_python', None):
            raise Refusal('use_explicit_adopt_for_config_changes')
        for field, requested in (("lane", args.lane), ("model", args.model)):
            if requested is not None and config["context"][field] != requested:
                raise Refusal("init_context_change_requires_selection")
        if args.repo_name is not None and config["repo"]["name"] != args.repo_name:
            raise Refusal("init_repository_name_mismatch")
    else:
        bounded = {"schema": 1, "repo": {"name": label(args.repo_name or root.name),
                  "id": str(uuid.uuid4()), "root": str(root)}, "context": {
                  "lane": token(args.lane or "product"), "model": label(args.model or "GPT-6 Astra")},
                  "runtime": runtime(), "vcs": "git"}
        config = normalize(encode(bounded), root=root).data
        authority = select(root, args)
        if authority == 'muse':
            config = bind_muse(root, config, getattr(args, 'muse_python', None))
            config['vcs']['regime'] = args.regime or 'muse-only'
            if getattr(args, 'muse_staging_remote', None):
                config['vcs']['muse']['staging_remote'] = args.muse_staging_remote
            if getattr(args, 'mirror_branch', None):
                config['vcs']['git']['mirror_branch'] = args.mirror_branch
        elif getattr(args, 'muse_python', None):
            raise Refusal('git_does_not_use_muse_python')
    config = normalize(encode(config), root=root).data
    observed = capture_context(root, existing, config)
    config_data = encode(config) if existing is None else existing
    current = read(root, NEXT, missing=True)
    if current is not None:
        validate_next(root, config, current, argparse.Namespace(), context=observed, freshness=False)
    ignore_expected = {}
    mapping = assets(root, config, args.hooks)
    if existing is None and config['vcs']['canonical'] == 'muse':
        tracked = tracked_bindings(root, config)
        if any(tracked.values()) and getattr(args, 'tracked_bindings', None) != 'preserve':
            raise Refusal('tracked_local_bindings: explicitly choose --tracked-bindings preserve or untrack separately')
        mapping.update(ignore_assets(root, expected=ignore_expected))
    if existing is not None:
        for row in classify_assets(root, mapping, config):
            if row["classification"] == "preserved":
                mapping.pop(row["path"])
            elif row["classification"] in ("consumer-modified", "both-changed"):
                raise Refusal("init_asset_modified: " + row["path"])
    preserved = {}
    binding_assets = {LAUNCHER, *HOOKS, "scripts/muse-bridge-deploy.sh"}
    for path in list(mapping):
        confined(root, path, missing_parents=True)
        old = read(root, path, missing=True)
        if existing is None and old is not None and path not in ('.gitignore', '.museignore'):
            if path in binding_assets:
                raise Refusal("init_asset_exists: " + path)
            # Existing portable skills, rules, policies and references remain
            # consumer-owned. Operational bindings still require exact adoption.
            preserved[path] = _snapshot(root, path)
            mapping.pop(path)
    for path, body in {"docs/ROADMAP.md": "# Roadmap\n\nCurrent action: docs/NEXT.md.\n",
                       "docs/OVERSEER-HANDOVER.md": "# Handover\n\nRead current action with `ok next`.\n"}.items():
        confined(root, path, missing_parents=True)
        if read(root, path, missing=True) is None:
            mapping[path] = body.encode()
    from cli.product_footprint import with_lock
    mapping = with_lock(root, mapping, config, preserved=preserved)
    if existing is None:
        mapping[CONFIG] = config_data  # Binding is committed after all other assets.

    def recheck():
        for relative, snapshot in preserved.items():
            if not _same(root, snapshot):
                raise Refusal("init_preserved_asset_changed: " + relative)
        for relative, expected_digest in ignore_expected.items():
            body = read(root, relative, missing=True)
            if ('absent' if body is None else digest(body)) not in (expected_digest, digest(mapping[relative])):
                raise Refusal('stale_write: ' + relative)
        if (read(root, CONFIG, missing=True) != existing or runtime() != config["runtime"] or
                capture_context(root, existing, config) != observed):
            raise Refusal("init_context_changed")

    # All destinations are preflighted without mutation before creating the
    # directory used for the ordinary advisory lock on a fresh installation.
    for path in mapping:
        confined(root, path, missing_parents=True)
    if not args.dry_run:
        confined(root, CONFIG, parents=True)
    changed = apply_mapping(root, mapping, check_context=recheck, dry_run=args.dry_run)
    if not args.dry_run and existing is None and current is None:
        initial = argparse.Namespace(action_id="SETUP", action_kind="plan", bound_id=args.bound_id,
                                     vcs=observed['vcs'], base_head=observed['head'])
        write_next(root, config, initial, "Choose the first task for this repository.\n",
                   expected="absent", context=capture_context(root, config_data))
    return {"ok": True, "repository": config["repo"], "initialized": not args.dry_run,
            "dry_run": args.dry_run, "changed": changed}


def parser():
    """Compatibility import for tests; there is one product parser."""
    from cli.main import parser as product_parser
    return product_parser()


def main(argv=None):
    """Compatibility engine seam; always uses production context validation."""
    from cli.main import main as dispatch
    return dispatch(argv)


if __name__ == "__main__":
    print("refused: launch with cli/ok", file=sys.stderr)
    raise SystemExit(2)

"""Deterministic portable source archives; local preparation, never publication."""
from __future__ import annotations
import argparse
import gzip
import hashlib
import io
import json
from pathlib import Path
import stat
import subprocess
import tarfile

ROOT = Path(__file__).resolve().parents[2]
MANIFEST = 'SOURCE-MANIFEST.json'
DIRECTORIES = {'adapters', 'cli', 'tools', 'cursor', 'policy', 'templates', 'desktop', 'scripts', 'tests', 'docs', '.github'}
FILES = {'VERSION', 'README.md', 'LICENSE', 'LICENSE.md', 'SECURITY.md', 'AGENTS.md', 'pyproject.toml',
         'requirements-v1.txt', 'requirements-v1-dev.txt', '.gitignore', '.museignore'}


def eligible(relative):
    p = Path(relative)
    if not p.parts or p.is_absolute() or '..' in p.parts or str(p) != relative:
        return False
    if p.parts[0] not in DIRECTORIES and relative not in FILES:
        return False
    if relative == 'docs/NEXT.md':
        return False
    if any(x in {'.git', '.muse', '.overseer', '.venv', '__pycache__', 'node_modules', 'target', 'resources', '.pytest_cache'}
           or x.endswith('.egg-info') for x in p.parts):
        return False
    if p.name.startswith('.env') or p.suffix.lower() in {'.pyc', '.pyo', '.pem', '.key', '.p12', '.pfx', '.p8'}:
        return False
    if p.name == 'apple-api-key.json' or 'private' in p.name.lower():
        return False
    return True


def source_files(root):
    if (root / MANIFEST).is_file() and not (root / '.git').exists():
        names = list(json.loads((root / MANIFEST).read_text())['files'])
    else:
        result = subprocess.run(['/usr/bin/git', '-C', str(root), 'ls-files', '-z', '--cached', '--others', '--exclude-standard'],
                                check=True, capture_output=True)
        names = result.stdout.decode().split('\0')
    result = {}
    for name in sorted(set(names)):
        if not eligible(name):
            continue
        p = root / name
        if p.is_symlink() or any(parent.is_symlink() for parent in p.parents if parent != root.parent):
            raise ValueError('source symlink: ' + name)
        if not p.is_file() or p.stat().st_nlink != 1:
            raise ValueError('source file missing or not regular: ' + name)
        result[name] = p
    required = ['cli/ok', 'cli/bootstrap.py', 'tools/app/static/index.html',
                'tools/hosted_dashboard/static/index.html', '.github/workflows/supported-v1.yml',
                'tools/ci/muse_artifact.py', 'cursor/skills/print-next/SKILL.md', 'templates/ROADMAP.template.md']
    for name in required:
        if name not in result:
            raise ValueError('required source missing: ' + name)
    return result


def manifest(root):
    return {'schema': 1, 'version': (root / 'VERSION').read_text().strip(),
            'kind': 'local-source-preparation', 'release_ready': False,
            'files': {name: {'sha256': hashlib.sha256(p.read_bytes()).hexdigest(),
                             'mode': '0755' if p.stat().st_mode & 0o111 else '0644', 'size': p.stat().st_size}
                      for name, p in source_files(root).items()}}


def build(root, output):
    root, output = root.resolve(strict=True), output.absolute()
    if output.exists() or output.is_symlink() or output.is_relative_to(root):
        raise ValueError('output must be a new path outside source')
    m = manifest(root)
    payload = json.dumps(m, indent=2, sort_keys=True).encode() + b'\n'
    with output.open('xb') as raw, gzip.GzipFile(fileobj=raw, mode='wb', filename='', mtime=0) as gz, tarfile.open(fileobj=gz, mode='w') as tar:
        for name in sorted([*m['files'], MANIFEST]):
            data = payload if name == MANIFEST else (root / name).read_bytes()
            info = tarfile.TarInfo(name)
            info.size = len(data)
            info.mode = 0o644 if name == MANIFEST else int(m['files'][name]['mode'], 8)
            info.mtime = info.uid = info.gid = 0
            info.uname = info.gname = ''
            tar.addfile(info, io.BytesIO(data))
    verify(output)
    return {'archive': str(output), 'sha256': hashlib.sha256(output.read_bytes()).hexdigest(),
            'manifest_sha256': hashlib.sha256(payload).hexdigest(), 'files': len(m['files'])}


def verify(archive):
    with tarfile.open(archive, 'r:gz') as tar:
        members = tar.getmembers()
        if len(members) > 20000 or sum(m.size for m in members) > 256 * 1024 * 1024:
            raise ValueError('archive bounds exceeded')
        names = [m.name for m in members]
        if len(names) != len(set(names)) or MANIFEST not in names:
            raise ValueError('duplicate paths or absent manifest')
        if any(not m.isfile() or m.mode not in (0o644, 0o755) or (m.name != MANIFEST and not eligible(m.name)) or m.size > 32 * 1024 * 1024 for m in members):
            raise ValueError('unsafe archive member')
        m = json.load(tar.extractfile(MANIFEST))
        if m.get('schema') != 1 or set(names) != set(m['files']) | {MANIFEST}:
            raise ValueError('manifest membership mismatch')
        for entry in members:
            if entry.name == MANIFEST:
                continue
            row = m['files'][entry.name]
            if (entry.mode != int(row['mode'], 8) or entry.size != row['size'] or
                    hashlib.sha256(tar.extractfile(entry).read()).hexdigest() != row['sha256']):
                raise ValueError('manifest mismatch: ' + entry.name)
    return m


def unpack(archive, destination):
    verify(archive)
    if destination.exists() or destination.is_symlink():
        raise ValueError('destination must be new')
    destination.mkdir(parents=True)
    with tarfile.open(archive, 'r:gz') as tar:
        tar.extractall(destination, filter='data')


def verify_tree(directory):
    m = json.loads((directory / MANIFEST).read_text())
    for name, row in m['files'].items():
        if not eligible(name):
            raise ValueError('unsafe resource path')
        p = directory / name
        if p.is_symlink() or any(parent.is_symlink() for parent in p.parents) or not p.is_file() or p.stat().st_nlink != 1:
            raise ValueError('invalid resource file: ' + name)
        if hashlib.sha256(p.read_bytes()).hexdigest() != row['sha256'] or (p.stat().st_mode & 0o777) != int(row['mode'], 8):
            raise ValueError('resource identity mismatch: ' + name)
    return m


def main():
    p = argparse.ArgumentParser(description=__doc__)
    sub = p.add_subparsers(dest='operation', required=True)
    b = sub.add_parser('build'); b.add_argument('--output', type=Path, required=True)
    v = sub.add_parser('verify'); v.add_argument('--archive', type=Path, required=True)
    u = sub.add_parser('unpack'); u.add_argument('--archive', type=Path, required=True); u.add_argument('--destination', type=Path, required=True)
    t = sub.add_parser('verify-tree'); t.add_argument('--directory', type=Path, required=True)
    a = p.parse_args()
    if a.operation == 'build':
        print(json.dumps(build(ROOT, a.output)))
    elif a.operation == 'verify':
        print(json.dumps({'ok': True, 'files': len(verify(a.archive)['files'])}))
    elif a.operation == 'verify-tree':
        print(json.dumps({'ok': True, 'files': len(verify_tree(a.directory)['files'])}))
    else:
        unpack(a.archive, a.destination)
        print(json.dumps({'ok': True, 'destination': str(a.destination)}))


if __name__ == '__main__':
    main()

"""Built-in L1 orchestrator algorithm (§K9.5)."""

from __future__ import annotations

import json
import os
import tempfile
from dataclasses import dataclass
from datetime import datetime, timezone
from pathlib import Path
from typing import Any, Callable

from adapters.config import CheckpointsConfig, OverseerConfig
from cli.atomic import WriteFailure, atomic_write_text
from cli.paths import PathEscapeError, confine_path, repo_relative
from tools.checkpoints.advance import compute_advance
from tools.checkpoints.artifact_hash import parse_artifact_sha256
from tools.checkpoints.argv_builder import build_verify_argv
from tools.checkpoints.executor import ExecResult, ScriptExecutor, SubprocessScriptExecutor
from tools.checkpoints.overrides import canonical_overrides_json
from tools.checkpoints.schema import (
    CheckpointSchemaError,
    load_manifest,
    load_policy,
    manifest_to_yaml,
    merge_overrides,
    render_progress,
    resolve_template_steps,
)
from tools.checkpoints.types import (
    ErrorToken,
    ManifestState,
    StepState,
    VerifyMode,
    VerifyStepJson,
    VerifyStepResult,
)


@dataclass
class VerifyStepOptions:
    """CLI options for verify-step."""

    manifest: str | None = None
    step_id: str | None = None
    through_current: bool = False
    verify_all: bool = False
    policy: str | None = None
    dry_run: bool = False
    emit_json: bool = False


def _utc_now_iso() -> str:
    return datetime.now(timezone.utc).replace(microsecond=0).isoformat().replace("+00:00", "Z")


def _step_json_entries(
    template_steps: list[str],
    manifest: ManifestState,
    selected: list[str],
) -> list[dict[str, Any]]:
    entries: list[dict[str, Any]] = []
    for step_id in template_steps:
        if step_id not in selected:
            continue
        state = manifest.steps.get(step_id, StepState())
        entries.append(
            {
                "id": step_id,
                "verified": state.verified,
                "artifact_sha256": state.artifact_sha256,
            }
        )
    return entries


def _result(
    *,
    exit_code: int,
    mode: VerifyMode | None,
    dry_run: bool,
    manifest_rel: str | None,
    steps: list[dict[str, Any]],
    error: ErrorToken,
) -> VerifyStepResult:
    payload = VerifyStepJson(
        ok=exit_code == 0,
        exit_code=exit_code,
        mode=mode,
        dry_run=dry_run,
        manifest=manifest_rel,
        steps=steps,
        error=error,
    )
    return VerifyStepResult(exit_code=exit_code, json_payload=payload)


def _resolve_mode(options: VerifyStepOptions) -> VerifyMode | None:
    if options.step_id is not None:
        return "step"
    if options.through_current:
        return "through"
    if options.verify_all:
        return "all"
    return None


def _validate_usage(options: VerifyStepOptions) -> VerifyStepResult | None:
    selectors = [
        options.step_id is not None,
        options.through_current,
        options.verify_all,
    ]
    if sum(1 for x in selectors if x) != 1:
        return _result(
            exit_code=1,
            mode=_resolve_mode(options),
            dry_run=options.dry_run,
            manifest_rel=options.manifest,
            steps=[],
            error="usage",
        )
    return None


def _select_through_current(
    template_steps: list[str],
    manifest: ManifestState,
) -> tuple[list[str] | None, VerifyStepResult | None]:
    """Return selected steps or a refusal result."""
    unverified = [sid for sid in template_steps if not manifest.steps[sid].verified]
    if not unverified:
        return [], None
    first_unverified = unverified[0]
    current_index = template_steps.index(manifest.current_step)
    first_index = template_steps.index(first_unverified)
    if first_index > current_index:
        return None, _result(
            exit_code=11,
            mode="through",
            dry_run=False,
            manifest_rel=None,
            steps=[],
            error="step_order",
        )
    end_index = current_index
    return template_steps[first_index : end_index + 1], None


def _is_executable(path: Path) -> bool:
    return path.is_file() and os.access(path, os.X_OK)


def run_verify_step(
    *,
    config: OverseerConfig,
    repo_root: Path,
    options: VerifyStepOptions,
    executor: ScriptExecutor | None = None,
    write_manifest: Callable[[Path, str], None] | None = None,
    write_progress: Callable[[Path, str], None] | None = None,
) -> VerifyStepResult:
    """Execute the built-in verify-step orchestrator."""
    exec_runner = executor or SubprocessScriptExecutor()
    manifest_writer = write_manifest or (
        lambda path, text: atomic_write_text(path, text)
    )
    progress_writer = write_progress or (
        lambda path, text: atomic_write_text(path, text)
    )
    mode = _resolve_mode(options)
    dry_run = options.dry_run

    usage_result = _validate_usage(options)
    if usage_result is not None:
        usage_result.json_payload.dry_run = dry_run
        return usage_result

    checkpoints = config.checkpoints
    if not checkpoints.enabled:
        return _result(
            exit_code=4,
            mode=mode,
            dry_run=dry_run,
            manifest_rel=None,
            steps=[],
            error="refused",
        )

    if checkpoints.orchestrator:
        return _run_consumer_override(
            config=config,
            repo_root=repo_root,
            options=options,
            mode=mode,
            executor=exec_runner,
        )

    manifest_rel, manifest_path, manifest_code = _resolve_manifest_path(
        repo_root, checkpoints, options.manifest
    )
    if manifest_code is not None:
        return _result(
            exit_code=manifest_code,
            mode=mode,
            dry_run=dry_run,
            manifest_rel=manifest_rel,
            steps=[],
            error="config" if manifest_code == 2 else "refused",
        )

    policy_rel, policy_path, policy_code = _resolve_policy_path(
        repo_root, checkpoints, options.policy
    )
    if policy_code is not None:
        return _result(
            exit_code=policy_code,
            mode=mode,
            dry_run=dry_run,
            manifest_rel=manifest_rel,
            steps=[],
            error="config" if policy_code == 2 else "refused",
        )

    try:
        policy = load_policy(policy_path)
        manifest = load_manifest(manifest_path)
        template_steps = resolve_template_steps(policy, manifest)
    except CheckpointSchemaError:
        return _result(
            exit_code=2,
            mode=mode,
            dry_run=dry_run,
            manifest_rel=manifest_rel,
            steps=[],
            error="config",
        )

    merged_overrides = merge_overrides(policy, manifest.template_id)

    if mode == "step":
        assert options.step_id is not None
        if options.step_id not in template_steps:
            return _result(
                exit_code=2,
                mode=mode,
                dry_run=dry_run,
                manifest_rel=manifest_rel,
                steps=[],
                error="config",
            )
        selected = [options.step_id]
    elif mode == "through":
        selected, refuse = _select_through_current(template_steps, manifest)
        if refuse is not None:
            refuse.json_payload.manifest = manifest_rel
            refuse.json_payload.dry_run = dry_run
            return refuse
        assert selected is not None
        if not selected:
            return _result(
                exit_code=0,
                mode=mode,
                dry_run=dry_run,
                manifest_rel=manifest_rel,
                steps=[],
                error=None,
            )
    else:
        selected = list(template_steps)

    if dry_run:
        for step_id in selected:
            order_refuse = _check_step_order(
                template_steps,
                manifest,
                step_id,
                selected,
                mode=mode,
                dry_run=True,
                manifest_rel=manifest_rel,
            )
            if order_refuse is not None:
                return order_refuse
            script_refuse = _check_script_path(
                repo_root, policy, step_id, mode, manifest_rel, template_steps, manifest, selected
            )
            if script_refuse is not None:
                script_refuse.json_payload.dry_run = True
                return script_refuse
        return _result(
            exit_code=0,
            mode=mode,
            dry_run=True,
            manifest_rel=manifest_rel,
            steps=_step_json_entries(template_steps, manifest, selected),
            error=None,
        )

    for step_id in selected:
        order_refuse = _check_step_order(
            template_steps,
            manifest,
            step_id,
            selected,
            mode=mode,
            dry_run=dry_run,
            manifest_rel=manifest_rel,
        )
        if order_refuse is not None:
            return order_refuse

        step_def = policy.steps[step_id]
        try:
            script_path = confine_path(repo_root, step_def.verify_script)
        except PathEscapeError:
            return _result(
                exit_code=4,
                mode=mode,
                dry_run=dry_run,
                manifest_rel=manifest_rel,
                steps=_step_json_entries(template_steps, manifest, selected),
                error="refused",
            )
        if not _is_executable(script_path):
            return _result(
                exit_code=4,
                mode=mode,
                dry_run=dry_run,
                manifest_rel=manifest_rel,
                steps=_step_json_entries(template_steps, manifest, selected),
                error="refused",
            )

        script_rel = repo_relative(repo_root, script_path)
        argv = build_verify_argv(
            verify_script=script_rel,
            manifest_rel=manifest_rel or "",
            step_id=step_id,
            policy_rel=policy_rel or "",
        )

        overrides_path: Path | None = None
        env = {
            "OVERSEER_REPO_ROOT": str(repo_root.resolve()),
            "OVERSEER_CHECKPOINT_PLACEHOLDER_TOKENS": json.dumps(
                policy.placeholder_tokens, ensure_ascii=False
            ),
        }
        try:
            with tempfile.NamedTemporaryFile(
                mode="w",
                encoding="utf-8",
                delete=False,
                suffix=".json",
            ) as handle:
                handle.write(canonical_overrides_json(merged_overrides))
                overrides_path = Path(handle.name)
            env["OVERSEER_CHECKPOINT_OVERRIDES_PATH"] = str(overrides_path.resolve())

            exec_result = exec_runner.exec_argv(
                argv,
                cwd=str(repo_root.resolve()),
                env=env,
            )
        finally:
            if overrides_path is not None:
                try:
                    overrides_path.unlink(missing_ok=True)
                except OSError:
                    pass

        if exec_result.exit_code != 0:
            result = _result(
                exit_code=10,
                mode=mode,
                dry_run=dry_run,
                manifest_rel=manifest_rel,
                steps=_step_json_entries(template_steps, manifest, selected),
                error="verify_fail",
            )
            if exec_result.stderr:
                result.stderr_extra = exec_result.stderr.decode("utf-8", errors="replace")
            return result

        sha = parse_artifact_sha256(exec_result.stdout)
        manifest.steps[step_id].verified = True
        manifest.steps[step_id].verified_at = _utc_now_iso()
        manifest.steps[step_id].artifact_sha256 = sha

        verified_map = {sid: manifest.steps[sid].verified for sid in template_steps}
        manifest.current_step = compute_advance(
            template_steps,
            step_id,
            verified_map,
            manifest.current_step,
        )

        try:
            manifest_writer(manifest_path, manifest_to_yaml(manifest))
            if checkpoints.progress:
                progress_path = _confine_optional(repo_root, checkpoints.progress)
                if progress_path is not None:
                    progress_writer(
                        progress_path,
                        render_progress(manifest, template_steps),
                    )
        except (WriteFailure, OSError):
            return _result(
                exit_code=5,
                mode=mode,
                dry_run=dry_run,
                manifest_rel=manifest_rel,
                steps=_step_json_entries(template_steps, manifest, selected),
                error="io",
            )

    return _result(
        exit_code=0,
        mode=mode,
        dry_run=dry_run,
        manifest_rel=manifest_rel,
        steps=_step_json_entries(template_steps, manifest, selected),
        error=None,
    )


def _confine_optional(repo_root: Path, user_path: str) -> Path | None:
    try:
        return confine_path(repo_root, user_path)
    except PathEscapeError:
        return None


def _resolve_manifest_path(
    repo_root: Path,
    checkpoints: CheckpointsConfig,
    manifest_arg: str | None,
) -> tuple[str | None, Path | None, int | None]:
    rel = manifest_arg or checkpoints.active_manifest
    if rel is None or not str(rel).strip():
        return None, None, 2
    try:
        path = confine_path(repo_root, rel)
    except PathEscapeError:
        return rel, None, 4
    if not path.is_file():
        return rel, None, 4
    return repo_relative(repo_root, path), path, None


def _resolve_policy_path(
    repo_root: Path,
    checkpoints: CheckpointsConfig,
    policy_arg: str | None,
) -> tuple[str | None, Path | None, int | None]:
    rel = policy_arg or checkpoints.policy
    if rel is None or not str(rel).strip():
        return None, None, 2
    try:
        path = confine_path(repo_root, rel)
    except PathEscapeError:
        return rel, None, 4
    if not path.is_file():
        return rel, None, 4
    return repo_relative(repo_root, path), path, None


def _check_step_order(
    template_steps: list[str],
    manifest: ManifestState,
    step_id: str,
    selected: list[str],
    *,
    mode: VerifyMode | None,
    dry_run: bool,
    manifest_rel: str | None,
) -> VerifyStepResult | None:
    """Refuse when a prior template step is not verified (§K9.5 step 6a)."""
    step_index = template_steps.index(step_id)
    selected_index = selected.index(step_id)
    earlier_in_run = set(selected[:selected_index])
    for prior_id in template_steps[:step_index]:
        if manifest.steps[prior_id].verified:
            continue
        if prior_id in earlier_in_run:
            continue
        return _result(
            exit_code=11,
            mode=mode,
            dry_run=dry_run,
            manifest_rel=manifest_rel,
            steps=_step_json_entries(template_steps, manifest, selected),
            error="step_order",
        )
    return None


def _check_script_path(
    repo_root: Path,
    policy,
    step_id: str,
    mode: VerifyMode | None,
    manifest_rel: str | None,
    template_steps: list[str],
    manifest: ManifestState,
    selected: list[str],
) -> VerifyStepResult | None:
    step_def = policy.steps[step_id]
    try:
        script_path = confine_path(repo_root, step_def.verify_script)
    except PathEscapeError:
        return _result(
            exit_code=4,
            mode=mode,
            dry_run=True,
            manifest_rel=manifest_rel,
            steps=_step_json_entries(template_steps, manifest, selected),
            error="refused",
        )
    if not _is_executable(script_path):
        return _result(
            exit_code=4,
            mode=mode,
            dry_run=True,
            manifest_rel=manifest_rel,
            steps=_step_json_entries(template_steps, manifest, selected),
            error="refused",
        )
    return None


def _run_consumer_override(
    *,
    config: OverseerConfig,
    repo_root: Path,
    options: VerifyStepOptions,
    mode: VerifyMode | None,
    executor: ScriptExecutor,
) -> VerifyStepResult:
    """Invoke consumer orchestrator override (§K9.5)."""
    orchestrator_rel = config.checkpoints.orchestrator
    assert orchestrator_rel
    try:
        script_path = confine_path(repo_root, orchestrator_rel)
    except PathEscapeError:
        return _result(
            exit_code=4,
            mode=mode,
            dry_run=options.dry_run,
            manifest_rel=options.manifest,
            steps=[],
            error="refused",
        )
    if not _is_executable(script_path):
        return _result(
            exit_code=4,
            mode=mode,
            dry_run=options.dry_run,
            manifest_rel=options.manifest,
            steps=[],
            error="refused",
        )
    argv = [repo_relative(repo_root, script_path)]
    # Pass through verify-step flags after script name.
    if options.manifest:
        argv.extend(["--manifest", options.manifest])
    if options.step_id:
        argv.extend(["--step", options.step_id])
    if options.through_current:
        argv.append("--through")
        argv.append("current")
    if options.verify_all:
        argv.append("--all")
    if options.policy:
        argv.extend(["--policy", options.policy])
    if options.dry_run:
        argv.append("--dry-run")
    if options.emit_json:
        argv.append("--json")

    env = {"OVERSEER_REPO_ROOT": str(repo_root.resolve())}
    exec_result = executor.exec_argv(
        argv,
        cwd=str(repo_root.resolve()),
        env=env,
    )
    if options.emit_json:
        # Override must emit JSON; pass through stdout unchanged via stderr_extra hack — CLI handles.
        return VerifyStepResult(
            exit_code=exec_result.exit_code,
            json_payload=VerifyStepJson(
                ok=exec_result.exit_code == 0,
                exit_code=exec_result.exit_code,
                mode=mode,
                dry_run=options.dry_run,
                manifest=options.manifest,
                steps=[],
                error=None if exec_result.exit_code == 0 else "refused",
            ),
            stderr_extra=exec_result.stderr.decode("utf-8", errors="replace"),
        )
    return VerifyStepResult(
        exit_code=exec_result.exit_code,
        json_payload=VerifyStepJson(
            ok=exec_result.exit_code == 0,
            exit_code=exec_result.exit_code,
            mode=mode,
            dry_run=options.dry_run,
            manifest=options.manifest,
            steps=[],
            error=None,
        ),
    )
